Maya Torres: Go (stream wrapper using pages + context cancellation):
```go
// demo-only: return channels so caller can select on ctx.Done()
func PagedStream(ctx context.Context, client *api.Client, save func(string,string) error, load func(string) (string, error), key string) (<-chan Item, <-chan error) {
  items := make(chan Item)
  errs := make(chan error, 1)
  go func() {
    defer close(items)
    cursor, _ := load(key)
    for {
      select {
      case <-ctx.Done():
        errs <- ctx.Err()
        return
      default:
      }
      page, err := client.FetchPage(ctx, cursor)
      if err != nil {
        // rudimentary retry
        time.Sleep(100 * time.Millisecond)
        continue
      }
      for _, it := range page.Items {
        items <- it
      }
      if page.Cursor == "" {
        return
      }
      cursor = page.Cursor
      save(key, cursor)
    }
  }()
  return items, errs
}
```

